<script setup lang="ts">
import {computed} from 'vue'
import type {Facets} from '@/api/practice'
import type {Filters} from '@/practice/catalog-query'
import {emptyFilters,examLabels,examTypes,listeningTypes} from '@/practice/catalog-query'
import PracticeDateFilter from './PracticeDateFilter.vue'
const props=defineProps<{modelValue:Filters;admin?:boolean;history?:boolean;examCodes?:string[];sourceLocked?:boolean;original?:boolean;section?:string;catalogLayout?:boolean;facets?:Facets;datesPending?:boolean}>(),emit=defineEmits<{'update:modelValue':[Filters];apply:[]}>()
const simple=computed(()=>props.catalogLayout&&!props.admin&&!props.original&&props.modelValue.source==='PAST'&&!props.history)
const countUnit=computed(()=>props.section==='reading'?'组':['writing','translation'].includes(props.section||'')?'题':'套')
function choose(key:keyof Filters,value:string){set(key,value);emit('apply')}
function dates(key:'year'|'month'){if(key==='year'&&props.catalogLayout)return Array.from({length:11},(_,i)=>String(2026-i));const values=new Set((props.facets?.[key]||[]).map(f=>f.value));return [...values].filter(v=>(key==='year'?/^\d{4}$/.test(v):/^\d+$/.test(v))&&(key!=='month'||Number(v)>=1&&Number(v)<=12)).sort((a,b)=>Number(b)-Number(a))}
function clear(){emit('update:modelValue',{...emptyFilters(props.admin),...(props.original?{exam:'',readingType:''}:{}),...(props.examCodes?{exam:props.examCodes[0]||'CET4'}:{}),...(props.sourceLocked||simple.value?{source:props.modelValue.source}:{})});emit('apply')}
const prominentDates=computed(()=>props.catalogLayout&&!props.original&&props.modelValue.source==='PAST')
const dateFields=[{key:'year' as const,label:'年份'},{key:'month' as const,label:'月份'},{key:'paperNo' as const,label:'套次'}]
const isListening=computed(()=>props.section==='listening'),typeOptions=computed(()=>isListening.value?(props.catalogLayout?[]:listeningTypes[props.modelValue.exam]||[]):(!props.section||props.section==='reading')?[...(examTypes[props.modelValue.exam||'CET4']||[]),...(props.admin&&(!props.modelValue.exam||props.modelValue.exam==='CET4')?[{code:'LISTENING',label:'整套听力',available:true},{code:'WRITING',label:'写作',available:true},{code:'TRANSLATION',label:'翻译',available:true}]:[])]:[])
function set(key:keyof Filters,value:string){const next={...props.modelValue,[key]:value,page:1};if(key==='exam'){next.readingType='';next.listeningType='';if(props.catalogLayout&&!props.admin)next.month=''}if(key==='year'&&props.catalogLayout&&!props.admin)next.month='';if(key==='source'&&value!=='PAST'){if(props.admin)next.exam='';next.year='';next.month='';next.paperNo=''}emit('update:modelValue',next)}
function change(key:keyof Filters,e:Event){set(key,(e.target as HTMLInputElement).value);emit('apply')}
</script>
<template><section v-if="simple" class="practice-filter-panel practice-simple-filters"><section class="practice-filter-group"><h3>类型 <span>{{examLabels[modelValue.exam]}}</span></h3><div class="practice-filter-chips"><button v-for="code in (examCodes||Object.keys(examLabels))" :key="code" :aria-label="'考试：'+examLabels[code]" :aria-pressed="modelValue.exam===code" @click="choose('exam',code)">{{examLabels[code]}}</button></div></section><section v-if="typeOptions.length" class="practice-filter-group"><h3>题型</h3><select aria-label="题型筛选" :value="modelValue.readingType" @change="change('readingType',$event)"><option value="">全部题型</option><option v-for="item in typeOptions" :key="item.code" :value="item.code">{{item.label}}{{item.available?'':' · 规划'}}</option></select></section><PracticeDateFilter v-for="item in [{key:'month' as const,label:'月份'},{key:'year' as const,label:'年份'}]" :key="item.key" :field="item.key" :label="item.label" :value="modelValue[item.key]" :values="dates(item.key)" :facets="facets?.[item.key]" :unit="countUnit" :disabled="item.key==='month'&&datesPending" @choose="choose(item.key,$event)"/><button class="practice-clear-filters" @click="clear">清空筛选</button></section><section v-else class="practice-filter-panel" :class="{'practice-admin-filters':admin}" :data-exam-filters="admin&&modelValue.source==='PAST'?'true':undefined"><form class="practice-filter-grid" @submit.prevent="emit('apply')"><input aria-label="搜索题组" :value="modelValue.q" placeholder="搜索英文或中文标题" maxlength="80" @input="set('q',($event.target as HTMLInputElement).value)"><select v-if="!original&&(!admin||modelValue.source==='PAST')" aria-label="考试类别筛选" :value="modelValue.exam" @change="change('exam',$event)"><option v-if="!examCodes" value="">全部考试</option><option v-for="code in (examCodes||Object.keys(examLabels))" :key="code" :value="code">{{examLabels[code]}}{{code!=='CET4'?' · 规划':''}}</option></select><select v-if="!original" :disabled="sourceLocked" aria-label="来源筛选" :value="modelValue.source" @change="change('source',$event)"><option value="">真题 / 原创</option><option value="ORIGINAL">原创练习</option><option value="PAST">真题</option></select><select v-if="!original&&typeOptions.length" aria-label="题型筛选" :value="isListening?modelValue.listeningType:modelValue.readingType" @change="change(isListening?'listeningType':'readingType',$event)"><option value="">{{isListening?'全部听力题型':'全部题型'}}</option><option v-for="item in typeOptions" :key="item.code" :value="item.code">{{item.label}}{{item.available?'':' · 规划'}}</option></select><select v-if="admin" aria-label="发布状态筛选" :value="modelValue.status" @change="change('status',$event)"><option value="">全部状态</option><option value="DRAFT">草稿</option><option value="PUBLISHED">已发布</option><option value="UNLISTED">已下架</option></select><select v-else aria-label="练习状态筛选" :value="modelValue.state" @change="change('state',$event)"><option value="">全部练习状态</option><option value="IN_PROGRESS">进行中</option><option value="COMPLETED">已完成</option><option v-if="!history" value="NOT_STARTED">未开始</option></select><label v-for="item in (prominentDates?dateFields.slice(0,2):[])" :key="item.key">{{item.label}}<select v-if="catalogLayout&&(item.key==='month'||item.key==='year')" :aria-label="'考试'+item.label+'筛选'" :value="modelValue[item.key]" :disabled="modelValue.source!=='PAST'||(item.key==='month'&&datesPending)" @change="change(item.key,$event)"><option value="">全部{{item.label}}</option><option v-for="value in dates(item.key as 'year'|'month')" :key="value" :value="value">{{value}}{{item.key==='month'?'月':'年'}}</option></select><input v-else type="number" :aria-label="'考试'+item.label+'筛选'" :value="modelValue[item.key]" placeholder="不限" @change="change(item.key,$event)"></label><button class="button-secondary">搜索</button></form><details><summary>{{original||(admin&&modelValue.source!=='PAST')?'主题筛选':prominentDates?'更多筛选 · 套次、主题':'更多筛选 · 年份、月份、套次、主题'}}</summary><div class="practice-more-filters"><template v-if="!original&&(!admin||modelValue.source==='PAST')"><label v-for="item in (prominentDates?dateFields.slice(2):dateFields)" :key="item.key">{{item.label}}<select v-if="catalogLayout&&(item.key==='month'||item.key==='year')" :aria-label="'考试'+item.label+'筛选'" :value="modelValue[item.key]" :disabled="modelValue.source!=='PAST'||(item.key==='month'&&datesPending)" @change="change(item.key,$event)"><option value="">全部{{item.label}}</option><option v-for="value in dates(item.key as 'year'|'month')" :key="value" :value="value">{{value}}{{item.key==='month'?'月':'年'}}</option></select><input v-else type="number" :aria-label="'考试'+item.label+'筛选'" :disabled="modelValue.source!=='PAST'" :value="modelValue[item.key]" placeholder="不限" @change="change(item.key,$event)"></label></template><label>主题<select :value="modelValue.topic" @change="change('topic',$event)"><option value="">全部主题</option><option value="education">教育</option><option value="culture">文化</option><option value="life">生活</option><option value="technology">科技</option></select></label></div><p v-if="!original" class="practice-hint">考试类别和时间仅用于真题；原创题按题型管理。</p></details><div class="practice-filter-foot"><label v-if="!catalogLayout||admin">排序 <select aria-label="题组排序" :value="modelValue.sort" @change="change('sort',$event)"><option :value="admin?'NEWEST':'LATEST'">{{admin?'最近创建':'最近发布'}}</option><option value="TITLE">名称 A–Z</option><option v-if="admin" value="COUNT">题数从多到少</option></select></label><button class="text-button" @click="emit('update:modelValue',{...emptyFilters(admin),...(original?{exam:'',readingType:''}:{}),...(examCodes?{exam:examCodes[0]||'CET4'}:{}),...(sourceLocked?{source:modelValue.source}:{})});emit('apply')">清空筛选</button></div></section></template>
